import { GoogleGenAI } from "@google/genai";

// Initialize Gemini Client
// WARNING: In a production environment, API calls should be proxied through a backend
// to protect the API key. For this client-side demo, we use the env variable directly.
const apiKey = process.env.API_KEY || '';

const ai = new GoogleGenAI({ apiKey });

export const generateExplanation = async (topic: string, context: string): Promise<string> => {
  if (!apiKey) return "عذراً، مفتاح API غير متوفر.";

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash',
      contents: `اشرح لي هذا الموضوع القانوني الجزائري بشكل مبسط للطلاب:
      الموضوع: ${topic}
      السياق: ${context}

      اجعل الشرح باللغة العربية الواضحة مع أمثلة من الواقع الجزائري.`,
      config: {
        tools: [{ googleSearch: {} }],
      }
    });

    // Check for grounding metadata (sources)
    const groundingMetadata = response.candidates?.[0]?.groundingMetadata;
    let text = response.text || "لم يتم العثور على إجابة.";

    if (groundingMetadata?.groundingChunks) {
        const sources = groundingMetadata.groundingChunks
            .filter((c: any) => c.web?.uri)
            .map((c: any) => `• [${c.web.title}](${c.web.uri})`)
            .join('\n');

        if (sources) {
            text += `\n\n**المصادر:**\n${sources}`;
        }
    }

    return text;
  } catch (error) {
    console.error("Error generating explanation:", error);
    return "حدث خطأ أثناء الاتصال بالذكاء الاصطناعي.";
  }
};

export const generateResearchPlan = async (title: string): Promise<string> => {
  if (!apiKey) return "عذراً، مفتاح API غير متوفر.";

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash',
      contents: `اقترح خطة بحث (Plan de recherche) لمذكرة تخرج حول الموضوع التالي: "${title}".
      يجب أن تكون الخطة ثنائية (مبحثين، كل مبحث مطلبين) وفق المنهجية القانونية الجزائرية.`,
      config: {
        tools: [{ googleSearch: {} }],
      }
    });
    return response.text || "لم يتم إنشاء خطة.";
  } catch (error) {
    console.error("Error generating plan:", error);
    return "حدث خطأ أثناء الاتصال بالذكاء الاصطناعي.";
  }
};

export const correctResearchMethodology = async (currentPlan: string, title: string): Promise<string> => {
  if (!apiKey) return "عذراً، مفتاح API غير متوفر.";

