      عنوان المذكرة: "${title}"
      الخطة المقترحة من الطالب:
      ${currentPlan}

      المطلوب:
      1. تقييم مدى احترام الخطة للمنهجية القانونية (التقسيم الثنائي المتوازن).
      2. تصحيح العناوين لتكون دقيقة وقانونية.
      3. اقتراح الخطة البديلة المصححة بالكامل (مبحثين، كل مبحث مطلبين).
      4. إعطاء نصائح منهجية حول الموضوع.

      استخدم أسلوباً أكاديمياً موجهاً للطالب.`,
      config: {
        tools: [{ googleSearch: {} }],
      }
    });
    return response.text || "لم يتم إنشاء تصحيح.";
  } catch (error) {
    console.error("Error correcting plan:", error);
    return "حدث خطأ أثناء الاتصال بالذكاء الاصطناعي.";
  }
};

export const analyzeDocumentImage = async (imageBase64: string, mimeType: string, prompt: string): Promise<string> => {
  if (!apiKey) return "عذراً، مفتاح API غير متوفر.";

